import {CATALOG} from './content.mjs';
import {escapeHTML as esc,safeURL,gradePractice,searchLessons,relatedSources,progressSummary,GRAPH,tutorFailure,tutorFailureText} from './core.mjs?v=2';
const $=id=>document.getElementById(id);
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const write=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}};
let lang=read('nabd-learning-language','ar')==='en'?'en':'ar';
const t=(ar,en)=>lang==='ar'?ar:en;
const text=value=>typeof value==='object'&&value?value[lang]||value.ar||value.en||'':String(value??'');
const key='nabd-learning-practice-v1';
let practice=read(key,{});if(!practice||Array.isArray(practice)||typeof practice!=='object')practice={};
let bookmarks=read('nabd-learning-bookmarks',[]);if(!Array.isArray(bookmarks))bookmarks=[];
let db=null,user=null,profile=null,enrollments=[],certificates=[],cloudCourses=[],cloudLessons=[],cloudQuestions=[],cloudProgress=[],rounds=[],posts=[],cloudAttempts=[],cloudSubmissions=[];
let accountStatus='',lmsStatus='',communityStatus='',roundsStatus='',accountReady=false,backendPromise=null,epoch=0;
let route='',query='',activeNode='heart',discussionStep=0,roundResults={},cloudFeedback=null,offlineState='';
const nav=[['universe','◎','Student Universe','عالمي التعليمي'],['learn','▤','NABD LMS','الدروس والاختبارات'],['tutor','✧','Medical Tutor','المساعد التعليمي'],['library','▥','Medical Library','المكتبة الطبية'],['graph','◇','Knowledge Graph','خريطة المعرفة'],['rounds','◉','Grand Rounds','الجلسات العلمية'],['scholarships','↗','Scholarships Hub','المنح والفرص'],['community','◌','Academic Community','المجتمع الأكاديمي'],['offline','↓','Offline Mode','التعلّم دون إنترنت']];
const icons={arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',book:'<path d="M12 5c-3-2-7-2-10-1v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1Zm0 0v15"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=name=>`<svg class="icon ${name==='arrow'?'arrow':''}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const btn=(url,label,secondary=false)=>`<a class="button ${secondary?'secondary':''}" href="${esc(url)}">${esc(label)}${icon('arrow')}</a>`;
const tag=label=>`<span class="tag">${esc(label)}</span>`;
function notice(message){$('notice').textContent=message;$('notice').hidden=!message}
function statusMessage(error){return ['42P01','PGRST205','42883','PGRST202'].includes(error?.code)?t('هذه الميزة تحتاج تفعيل قاعدة البيانات من الإدارة. ما زالت الدروس العامة متاحة.','This feature needs database activation by the academy. Public lessons remain available.'):t('تعذر تحميل البيانات. تحقق من اتصالك ثم حاول مجددًا.','Could not load data. Check your connection and try again.')}
const checked=async query=>{const r=await query;if(r.error)throw r.error;return r.data};
function sourceLinks(ids){return CATALOG.sources.filter(s=>ids.includes(s.id)).map(s=>`<a href="${esc(safeURL(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ${icon('arrow')}</a>`).join('')}
function titleCourse(id){const c=cloudCourses.find(c=>String(c.id)===String(id));return c?(lang==='ar'?c.title_ar||c.title_en||c.title:c.title_en||c.title_ar||c.title)||id:id}
function shell(){
 document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';
 document.title=t('مساحة التعلّم | أكاديمية نبض للعلوم الطبية','Learning Space | NABD Academy for Medical Sciences');
 $('brand-name').innerHTML=t('أكاديمية نبض<small>للعلوم الطبية · منذ 2023</small>','NABD Academy<small>for Medical Sciences · Since 2023</small>');
 $('language').textContent=lang==='ar'?'English':'العربية';
 $('account-link').textContent=user?(profile?.full_name||t('حسابي','My account')):t('حسابي','My account');
 $('legacy-portal').textContent=t('بوابة الطالب والشهادات ←','Student portal & certificates →');
 $('lecturer-link').textContent=t('بوابة المحاضرين ←','Lecturer portal →');
 $('home-link').textContent=t('الموقع الرئيسي ←','Academy home →');
 $('founder-link').textContent=t('المؤسس: محمد خالد العرجا','Founder: Mohammed Khaled Al-Arja');
 $('policies-link').textContent=t('السياسات والخصوصية','Policies & privacy');
 $('connectivity').textContent=navigator.onLine?t('متصل','Online'):t('دون اتصال','Offline');
 $('connectivity').classList.toggle('offline',!navigator.onLine);
 $('navigation').innerHTML=nav.map(([id,symbol,en,ar])=>`<a href="#${id}" ${route.split('/')[0]===id||route.startsWith('lesson/')&&id==='learn'||route.startsWith('course/')&&id==='learn'?'aria-current="page"':''}><span class="nav-symbol" aria-hidden="true">${symbol==='↗'?icon('arrow'):symbol}</span><span>${esc(t(ar,en))}</span></a>`).join('');
 $('page-title').textContent=route.startsWith('lesson/')?text(CATALOG.lessons.find(l=>l.id===route.split('/')[1])?.title)||t('الدرس','Lesson'):route.startsWith('course/')?t('دروس الدورة','Course lessons'):route==='account'?t('حسابك في نبض','Your NABD account'):nav.find(n=>n[0]===route)?.[lang==='ar'?3:2]||t('عالمي التعليمي','Student Universe');
}
function searchbar(placeholder,extra=''){return `<div class="toolbar"><label class="search"><span class="sr-only">${esc(placeholder)}</span><input id="search" type="search" value="${esc(query)}" placeholder="${esc(placeholder)}"></label>${extra}</div>`}
function lessonCard(l){const done=practice[l.id]?.completed;return `<a class="lesson-card" href="#lesson/${esc(l.id)}"><div class="lesson-art art-${esc(l.topic)}"><span class="chapter">${String(l.number).padStart(2,'0')}</span>${icon('book')}<span>${esc(l.topic.toUpperCase())}</span></div><div class="lesson-card-body"><div class="row">${tag(t('درس تأسيسي عام','Public foundation lesson'))}<small>${l.minutes} ${t('دقائق','min')}</small></div><h3>${esc(text(l.title))}</h3><p>${esc(text(l.objectives))}</p><div class="card-bottom"><span>${done?t('قرأت هذا الدرس','You marked this read'):t('ابدأ الدرس','Start lesson')}</span>${icon(done?'check':'arrow')}</div></div></a>`}
function universe(){
 const progress=progressSummary(CATALOG.lessons,practice),next=CATALOG.lessons.find(l=>!practice[l.id]?.completed)||CATALOG.lessons[0];
 return `<section class="hero-panel"><div><span class="eyebrow">NABD · STUDENT UNIVERSE</span><h2>${esc(user?t('مرحبًا، '+(profile?.full_name||'زميلنا في نبض'),'Welcome, '+(profile?.full_name||'NABD learner')):t('معرفتك تنمو.\nوآفاقك تتّسع.','Grow your knowledge.\nExpand your possibilities.'))}</h2><p>${esc(t('تعلّم بفهم، اختبر معرفتك، وابنِ خطوتك التالية. مساحة واحدة تجمع رحلتك، مهما كانت ظروف اتصالك.','Learn with purpose, test your understanding and build your next step. One space for your journey, whatever your connection.'))}</p><div class="actions">${btn('#learn',t('ابدأ التعلّم','Start learning'))}${btn('#offline',t('تعلّم دون إنترنت','Learn offline'),true)}</div></div><div class="orbit" aria-hidden="true"><div class="orbit-ring one"></div><div class="orbit-ring two"></div><div class="orbit-center">N<span>LEARN · CONNECT · GROW</span></div><span class="orbit-dot dot-one">+</span><span class="orbit-dot dot-two">◇</span><span class="orbit-dot dot-three">◉</span></div></section>
 <section class="stat-grid" aria-label="${t('ملخص رحلتك','Learning summary')}"><article><span>${esc(t('دوراتي الحالية','My enrolled courses'))}</span><strong>${user?enrollments.length:'—'}</strong><small>${esc(user?t('السجلات المحمّلة من حسابك','Loaded from your account'):t('اربط حسابك لعرض دوراتك','Connect your account to view courses'))}</small></article><article><span>${esc(t('شهاداتي','My certificates'))}</span><strong>${user?certificates.length:'—'}</strong><small>${esc(t('عرض الشهادات في البوابة الحالية','View certificates in the existing portal'))}</small></article><article><span>${esc(t('دروس قرأتها','Lessons marked read'))}</span><strong dir="ltr">${progress.completed}<i> / ${CATALOG.lessons.length}</i></strong><small>${esc(t('تدريب عام على هذا الجهاز','Public practice on this device'))}</small></article><article><span>${esc(t('نقاط التدريب','Practice points'))}</span><strong>${progress.points}</strong><small>${esc(t('محلية؛ لا تمنح شهادة أو اعتمادًا','Local; no certificate or accreditation'))}</small></article></section>
 <div class="dashboard-grid"><section class="panel continue-card"><div class="section-title"><div><span class="eyebrow">YOUR NEXT CHAPTER</span><h2>${esc(t('خطوتك التالية','Your next step'))}</h2></div><span class="progress-ring" style="--progress:${progress.percent}%"><span>${progress.percent}%</span></span></div><h3>${esc(text(next.title))}</h3><p>${esc(text(next.objectives))}</p>${btn('#lesson/'+next.id,t('تابع التعلّم','Continue learning'))}<small>${esc(t('التقدم هنا للحزمة العامة على هذا الجهاز، وليس نتيجة رسمية للدورات.','This is device progress for the public pack, not an official course result.'))}</small></section><section class="panel focus-panel"><span class="eyebrow">A CONNECTED WAY TO LEARN</span><h2>${esc(t('اربط المعلومة بالصورة الكبيرة','See the bigger picture'))}</h2><p>${esc(t('من التشريح إلى الفيزيولوجيا والمرض والدواء: خريطة تساعدك على رؤية الروابط.','From anatomy to physiology, conditions and medicines: explore how concepts connect.'))}</p>${btn('#graph',t('افتح خريطة المعرفة','Explore the Knowledge Graph'),true)}<div class="mini-nodes" aria-hidden="true"><span>ANATOMY</span><b>···</b><span>PHYSIOLOGY</span><b>···</b><span>MEDICINE</span></div></section></div>
 <section class="practice-achievements" aria-label="${t('إنجازات التدريب المحلي','Local practice achievements')}"><span>${esc(t('إنجازات التدريب · على هذا الجهاز','Practice achievements · On this device'))}</span>${[[progress.completed>0,'انطلاقة التعلّم','Learning started'],[progress.passed>0,'استرجاع متقن','Successful retrieval'],[progress.completed===CATALOG.lessons.length,'قراءة الحزمة كاملة','Full pack read']].map(([unlocked,a,e])=>`<span class="achievement ${unlocked?'unlocked':''}" aria-label="${esc(text({ar:a,en:e})+' · '+(unlocked?t('مكتمل','Unlocked'):t('لم يكتمل بعد','Not yet unlocked')))}">${icon(unlocked?'check':'book')}${esc(t(a,e))}</span>`).join('')}</section>
 <section class="section"><div class="section-title"><h2>${esc(t('دوراتك في الأكاديمية','Your academy courses'))}</h2>${btn('../portal.html',t('بوابة الطالب الحالية','Existing student portal'),true)}</div>${accountStatus?`<p class="notice-inline">${esc(accountStatus)}</p>`:''}${user?(enrollments.length?`<div class="course-grid">${enrollments.map(e=>`<a class="panel course-card" href="#course/${encodeURIComponent(String(e.course_id))}">${tag(t('دورة مسجّل بها','Enrolled course'))}<h3>${esc(titleCourse(e.course_id))}</h3><p>${esc(t('افتح دروس الدورة المتاحة لحسابك.','Open the course lessons available to your account.'))}</p><span class="text-link">${esc(t('افتح الدورة','Open course'))} ${icon('arrow')}</span></a>`).join('')}</div>`:`<p class="empty">${esc(t('لا توجد تسجيلات في النتائج المحمّلة. راجع بوابتك الحالية أو تواصل مع الإدارة.','No enrollments in the loaded results. Check the existing portal or contact the academy.'))}</p>`):`<div class="empty">${esc(t('سجّل الدخول بحسابك الحالي لعرض دوراتك وشهاداتك. الدروس العامة متاحة دون تسجيل.','Sign in with your existing account for your courses and certificates. Public lessons need no sign-in.'))} ${btn('#account',t('ربط حسابي','Connect my account'))}</div>`}</section>
 <section class="section"><div class="section-title"><h2>${esc(t('تعلّم على طريقتك','Learn your way'))}</h2><a class="text-link" href="#library">${esc(t('المكتبة الطبية','Medical Library'))} ${icon('arrow')}</a></div><div class="lesson-grid">${CATALOG.lessons.slice(0,3).map(lessonCard).join('')}</div></section>`;
}
function learn(){return `<div class="intro"><span class="eyebrow">NABD · LEARNING MANAGEMENT</span><h2>${esc(t('افهم. جرّب. راجع.','Understand. Practice. Review.'))}</h2><p>${esc(t('ابدأ بالحزمة التأسيسية العامة، أو افتح دورة من حسابك. اختبارات الحزمة للتدريب الذاتي ولا تصدر شهادات.','Start with the public foundation pack, or open an enrolled course. Pack quizzes are self-study practice and do not issue certificates.'))}</p></div>${searchbar(t('ابحث في الدروس والأهداف','Search lessons and objectives'))}<div id="results" class="lesson-grid">${searchLessons(CATALOG,query).map(lessonCard).join('')||`<p class="empty">${t('لا توجد نتائج.','No results.')}</p>`}</div><div class="panel section"><h2>${esc(t('الدورات والموارد الحالية','Existing courses and resources'))}</h2><p>${esc(t('تظل دوراتك وشهاداتك وسجلاتك في البوابة الحالية. محتوى المحاضرين متاح من استوديو التدريس وفق صلاحياتك.','Your courses, certificates and records remain in the existing portal. Lecturer resources are available through the Teaching Studio according to your access.'))}</p><div class="actions">${btn('../portal.html',t('بوابة الطالب','Student portal'))}${btn('../lecturers.html',t('موارد المحاضرين','Lecturer resources'),true)}</div></div>`}
function lessonView(id){
 const l=CATALOG.lessons.find(x=>x.id===id);if(!l)return `<p class="empty">${t('الدرس غير موجود.','Lesson not found.')}</p>`;
 return `<a class="text-link" href="#learn">${esc(t('جميع الدروس','All lessons'))} ${icon('arrow')}</a><div class="lesson-layout"><article class="panel reading"><div class="row">${tag(t('حزمة عامة · تعلّم ذاتي','Public pack · Self-study'))}<span>${l.minutes} ${t('دقائق','min')}</span></div><h2>${esc(text(l.title))}</h2><p class="objective"><b>${esc(t('هدف التعلّم','Learning objective'))}</b> ${esc(text(l.objectives))}</p>${l.sections.map((s,i)=>`<section><span class="section-number">0${i+1}</span><h3>${esc(text(s.heading))}</h3><p>${esc(text(s.text))}</p></section>`).join('')}<div class="sources"><h3>${esc(t('راجع المصادر','Explore the sources'))}</h3>${sourceLinks(l.source_ids)}</div><button class="button" data-read="${l.id}">${practice[l.id]?.completed?t('قرأت هذا الدرس ✓','Marked as read ✓'):t('تمّت قراءة الدرس','Mark lesson as read')}${icon('check')}</button><small>${esc(t('يُحفظ على هذا الجهاز فقط.','Saved on this device only.'))}</small></article><aside class="panel quiz-panel"><span class="eyebrow">RETRIEVAL PRACTICE</span><h2>${esc(t('اختبر فهمك','Check your understanding'))}</h2><p>${esc(t('تدريب ذاتي بنتيجة فورية وشرح الإجابات.','Self-study practice with immediate feedback and explanations.'))}</p><form id="practice-quiz" data-lesson="${l.id}">${l.quiz.map((q,i)=>`<fieldset><legend>${i+1}. ${esc(text(q.prompt))}</legend>${q.choices.map((c,j)=>`<label class="choice"><input type="radio" name="${q.id}" value="${j}" required><span>${esc(text(c))}</span></label>`).join('')}</fieldset>`).join('')}<button class="button">${esc(t('صحّح إجاباتي','Check my answers'))}</button></form><div id="practice-result" role="status" aria-live="polite"></div></aside></div>`;
}
function library(){const topic=read('nabd-learning-library-topic','all');return `<div class="intro"><span class="eyebrow">KNOWLEDGE, RESPONSIBLY SHARED</span><h2>${esc(t('المعرفة الطبية، من مصادرها.','Medical knowledge, from its sources.'))}</h2><p>${esc(t('دليل موارد قانونية: كتب مفتوحة، مراجع، مقالات وقواعد أدلة. نربط بالمصدر الأصلي ونوضح اختلاف حقوق القراءة وإعادة الاستخدام.','A legal resource directory: open textbooks, references, articles and evidence databases. We link to originals and distinguish reading access from reuse rights.'))}</p></div>${searchbar(t('ابحث عن مصدر أو مجال','Search a source or subject'),`<select id="library-topic" aria-label="${t('المجال','Subject')}">${[['all','كل المجالات','All subjects'],['anatomy','تشريح','Anatomy'],['physiology','فيزيولوجيا','Physiology'],['terminology','مصطلحات','Terminology'],['research','بحث علمي','Research'],['saved','المحفوظة','Saved']].map(([id,ar,en])=>`<option value="${id}" ${topic===id?'selected':''}>${t(ar,en)}</option>`).join('')}</select>`)}<div id="library-results" class="resource-grid">${libraryCards(topic)}</div>`}
function libraryCards(topic){return CATALOG.sources.filter(s=>(topic==='all'||s.topic===topic||topic==='saved'&&bookmarks.includes(s.id))&&JSON.stringify([s.title,s.note,s.topic]).toLocaleLowerCase().includes(query.toLocaleLowerCase())).map(s=>`<article class="panel library-card"><div class="row">${tag(s.topic)}<button class="save-button" data-bookmark="${s.id}" aria-pressed="${bookmarks.includes(s.id)}" aria-label="${esc(t('حفظ المصدر','Save resource'))}">${icon(bookmarks.includes(s.id)?'check':'book')}</button></div><h3>${esc(s.title)}</h3><p>${esc(text(s.note))}</p><a class="text-link" href="${esc(safeURL(s.url))}" target="_blank" rel="noopener noreferrer">${esc(t('افتح المصدر الرسمي','Open official source'))} ${icon('arrow')}</a></article>`).join('')||`<p class="empty">${t('لا توجد مصادر مطابقة.','No matching sources.')}</p>`}
function graph(){const node=GRAPH.nodes.find(n=>n.id===activeNode)||GRAPH.nodes[0],near=new Set(GRAPH.edges.filter(e=>e.includes(node.id)).flat());return `<div class="intro"><span class="eyebrow">NABD · KNOWLEDGE GRAPH</span><h2>${esc(t('لا تحفظ المعلومة وحدها. اربطها.','Connect facts. Build understanding.'))}</h2><p>${esc(t('اضغط مفهومًا لرؤية علاقاته ومصدره. خريطة تأسيسية تعليمية، وليست أداة تشخيص أو توصية علاجية.','Select a concept to explore its connections and source. A foundation learning map, not a diagnostic or treatment tool.'))}</p></div><div class="graph-layout"><section class="panel graph-panel"><div class="graph-legend">${tag(t('تشريح','Anatomy'))}${tag(t('فيزيولوجيا','Physiology'))}${tag(t('مرض ودواء','Conditions & medicines'))}</div><svg viewBox="0 0 630 475" class="knowledge-map" role="img" aria-label="${esc(t('العلاقات بين القلب والدم والأكسجين والضغط','Connections between heart, blood, oxygen and pressure'))}">${GRAPH.edges.map(([a,b])=>{const x=GRAPH.nodes.find(n=>n.id===a),y=GRAPH.nodes.find(n=>n.id===b);return `<line x1="${x.x}" y1="${x.y}" x2="${y.x}" y2="${y.y}" class="${a===node.id||b===node.id?'edge active':'edge'}"/>`}).join('')}${GRAPH.nodes.map(n=>`<g class="graph-node ${n.id===node.id?'selected':near.has(n.id)?'neighbor':''}" data-node="${n.id}"><circle cx="${n.x}" cy="${n.y}" r="${n.id===node.id?35:27}"/><text x="${n.x}" y="${n.y+51}" text-anchor="middle">${esc(text(n.label))}</text><text x="${n.x}" y="${n.y+5}" text-anchor="middle" class="node-glyph">${n.group==='anatomy'?'+':n.group==='physiology'?'◎':'◇'}</text></g>`).join('')}</svg><div class="node-buttons" aria-label="${t('اختيار مفهوم','Choose a concept')}">${GRAPH.nodes.map(n=>`<button type="button" data-node="${n.id}" aria-pressed="${node.id===n.id}">${esc(text(n.label))}</button>`).join('')}</div></section><aside class="panel graph-detail"><span class="eyebrow">EXPLORE THE CONNECTION</span><h2>${esc(text(node.label))}</h2><p>${esc(text(node.summary))}</p><h3>${esc(t('يرتبط بـ','Connected to'))}</h3><div class="node-buttons">${GRAPH.nodes.filter(n=>n.id!==node.id&&near.has(n.id)).map(n=>`<button data-node="${n.id}">${esc(text(n.label))}</button>`).join('')}</div><div class="sources">${sourceLinks(node.sources)}</div>${btn('#lesson/circulation',t('تعلّم الدورة الدموية','Study circulation'))}</aside></div>`}
function tutor(){return `<div class="intro"><span class="eyebrow">NABD · MEDICAL TUTOR</span><h2>${esc(t('سؤال جيد، وفهم أعمق.','Better questions. Deeper understanding.'))}</h2><p>${esc(t('ابحث في ملخصات نبض المرفقة بالمصادر، أو استخدم المساعد التوليدي بعد تفعيله من الإدارة. لا ترفع صور مرضى أو معلومات شخصية.','Search NABD’s source-linked summaries, or use the generative tutor after academy activation. Do not upload patient images or personal information.'))}</p></div><div class="tutor-layout"><section class="panel"><div class="tutor-mark">${icon('spark')}</div><h2>${esc(t('ما الذي تتعلّمه اليوم؟','What are you learning today?'))}</h2><div class="suggestions">${[['القلب والدورة الدموية','Heart and circulation'],['أجزاء المصطلح الطبي','Medical word parts'],['الارتباط والسببية','Association and causation']].map(([a,e])=>`<button type="button" data-suggest="${esc(t(a,e))}">${esc(t(a,e))}</button>`).join('')}</div><form id="tutor-form"><label>${esc(t('سؤالك التعليمي','Your learning question'))}<textarea name="question" maxlength="1500" rows="4" required placeholder="${esc(t('مثال: اشرح الفرق بين الشريان والوريد','Example: Explain the difference between arteries and veins'))}"></textarea></label><label class="upload-label">${esc(t('صورة تعليمية اختيارية للمساعد التوليدي (PNG / JPEG، حتى 2MB)','Optional educational image for the generative tutor (PNG / JPEG, up to 2MB)'))}<input type="file" name="image" accept="image/png,image/jpeg"></label><div class="actions"><button class="button" name="mode" value="reference">${esc(t('ابحث في الحزمة المرجعية','Search the reference pack'))}</button><button class="button secondary" name="mode" value="ai">${esc(t('اسأل AI Tutor','Ask AI Tutor'))}${icon('spark')}</button></div></form><div id="tutor-result" class="tutor-result" role="status" aria-live="polite"></div></section><aside class="panel"><span class="eyebrow">UNDERSTAND, THEN VERIFY</span><h2>${esc(t('مساعد للتعلّم','A learning companion'))}</h2><ul class="spaced-list"><li>${esc(t('البحث المرجعي يعرض فقرات الحزمة؛ لا يولّد إجابات جديدة.','Reference search displays pack passages; it does not generate new answers.'))}</li><li>${esc(t('التوليد وشرح الصور يتطلبان اتصالًا وحسابًا وخدمة مفعّلة.','Generation and image explanation need connectivity, an account and an activated service.'))}</li><li>${esc(t('راجع الإجابات في المراجع؛ ولا تستخدمها لاتخاذ قرار طبي لشخص.','Verify answers against references; do not use them for personal medical decisions.'))}</li></ul>${btn('#library',t('افتح المكتبة الطبية','Open the Medical Library'),true)}</aside></div>`}
function roundsView(){const steps=[
 {title:t('الحالة التعليمية','The learning vignette'),body:t('في سيناريو لغوي افتراضي، صادفت كلمة bradycardia في ملخص. لا توجد بيانات مريض. كيف تحلل المصطلح قبل تفسيره؟','In a fictional terminology vignette, you encounter bradycardia in a summary. No patient data is involved. How would you analyze the term before interpreting it?')},
 {title:t('صوت الطالب: فكّ الأجزاء','Learner perspective: decode the parts'),body:t('brady- = بطيء، وcardi = قلب، و-ia = حالة. الوصف اللغوي هو بطء معدل القلب، ولا يخبرنا وحده بالسبب.','brady- = slow, cardi = heart, -ia = condition. The word describes a slow heart rate; it does not identify the cause.')},
 {title:t('صوت المراجع: تحقّق من السياق','Reviewer perspective: verify context'),body:t('نراجع المعنى في MedlinePlus Medical Words. نميّز التعريف اللغوي عن التقييم السريري، ونمتنع عن استنتاج تشخيص من كلمة فقط.','Check the definition in MedlinePlus Medical Words. Distinguish word meaning from clinical assessment and avoid inferring a diagnosis from a term alone.')}];
 return `<div class="intro"><span class="eyebrow">NABD · GRAND ROUNDS</span><h2>${esc(t('نتعلّم حين نناقش.','We learn through discussion.'))}</h2><p>${esc(t('جلسات علمية تنشرها الأكاديمية، ومحاكاة قصيرة لطريقة تفكيك حالة تعليمية ومراجعة مصادرها.','Academy-published scientific sessions and a short guided simulation for analyzing a learning vignette and its sources.'))}</p></div><div class="dashboard-grid"><section class="panel discussion"><span class="tag">${esc(t('محاكاة مكتوبة · ليست جلسة حية','Scripted simulation · Not a live session'))}</span><div class="step-dots">${steps.map((_,i)=>`<span class="${i<=discussionStep?'active':''}">${i+1}</span>`).join('')}</div><h2>${esc(steps[discussionStep].title)}</h2><p>${esc(steps[discussionStep].body)}</p><div class="actions"><button class="button" data-discussion="${(discussionStep+1)%3}">${esc(discussionStep===2?t('ابدأ من جديد','Start again'):t('تابع المناقشة','Continue discussion'))}${icon('arrow')}</button>${btn('../atlas/clinical-hub.html',t('محاكاة حالات المستشفى','Hospital case simulation'),true)}</div><div class="sources">${sourceLinks(['medterms'])}</div></section><section class="panel"><span class="eyebrow">ACADEMY SESSIONS</span><h2>${esc(t('الجلسات المنشورة','Published sessions'))}</h2>${roundsStatus?`<p class="notice-inline">${esc(roundsStatus)}</p>`:''}${rounds.length?rounds.map(r=>`<article class="round-card"><span>${esc(new Intl.DateTimeFormat(lang,{dateStyle:'medium',timeStyle:'short'}).format(new Date(r.starts_at)))}</span><h3>${esc(r.title)}</h3><p>${esc(r.speaker||'')}</p><p>${esc(r.description||'')}</p>${safeURL(r.meeting_url)?`<a class="text-link" href="${esc(safeURL(r.meeting_url))}" target="_blank" rel="noopener noreferrer">${esc(t('رابط الجلسة','Session link'))} ${icon('arrow')}</a>`:''}</article>`).join(''):`<p class="empty">${esc(t('لا توجد جلسات محمّلة حاليًا. تظهر هنا الجلسات التي تعتمدها الإدارة.','No sessions are loaded. Sessions approved by the academy will appear here.'))}</p>`}<small>${esc(t('الأوقات بحسب توقيت جهازك: ','Times use your device timezone: ')+Intl.DateTimeFormat().resolvedOptions().timeZone)}</small></section></div>`;
}
function scholarships(){return `<div class="intro"><span class="eyebrow">NABD · SCHOLARSHIPS HUB</span><h2>${esc(t('المعرفة تفتح أبوابًا.','Knowledge opens doors.'))}</h2><p>${esc(t('دليل برامج رسمية لاستكشاف فرص الدراسة والبحث حول العالم. ليست إعلانات عن قبول أو تمويل مضمون؛ تحقّق من الأهلية والمواعيد الحالية في كل مصدر.','Explore official study and research programs worldwide. These are not offers of guaranteed admission or funding. Verify current eligibility and deadlines at each source.'))}</p></div><div class="resource-grid">${CATALOG.scholarships.map(s=>`<article class="panel scholarship-card">${tag(text(s.region))}<h3>${esc(s.title)}</h3><strong>${esc(text(s.type))}</strong><p>${esc(text(s.note))}</p><a class="text-link" href="${esc(safeURL(s.url))}" target="_blank" rel="noopener noreferrer">${esc(t('الشروط من المصدر الرسمي','Official requirements'))} ${icon('arrow')}</a></article>`).join('')}</div><section class="panel section"><h2>${esc(t('جهّز ملفك خطوة بخطوة','Prepare your application step by step'))}</h2><p>${esc(t('قائمة تنظيمية محلية؛ لا تُرفع ملفاتك الشخصية.','A local checklist; your personal documents are not uploaded.'))}</p><div class="checklist">${[['cv','سيرة ذاتية محدّثة','Updated CV'],['language','متطلبات اللغة','Language requirements'],['transcript','كشف الدرجات','Academic transcript'],['motivation','رسالة الدافع','Motivation letter'],['references','متطلبات التوصيات','Reference requirements']].map(([id,a,e])=>`<label><input type="checkbox" data-checklist="${id}" ${read('nabd-learning-checklist',{})[id]?'checked':''}>${esc(t(a,e))}</label>`).join('')}</div></section>`}
function community(){return `<div class="intro"><span class="eyebrow">NABD · ACADEMIC COMMUNITY</span><h2>${esc(t('تعلّم مع الآخرين.','Learn with others.'))}</h2><p>${esc(t('أسئلة ومراجع وتجارب تعلّم يراجعها المشرفون قبل نشرها. لا تشارك معلومات مرضى أو بيانات اتصال خاصة.','Questions, resources and learning experiences reviewed by moderators before publication. Do not share patient information or private contact details.'))}</p></div><div class="community-layout"><section class="panel"><h2>${esc(t('أضف مساهمة علمية','Share a learning contribution'))}</h2>${communityStatus?`<p class="notice-inline">${esc(communityStatus)}</p>`:''}${user?`<form id="community-form"><label>${esc(t('اسم العرض','Display name'))}<input name="display_name" maxlength="60" required autocomplete="nickname"></label><label>${esc(t('المجال','Topic'))}<select name="topic"><option value="learning">${t('سؤال تعليمي','Learning question')}</option><option value="research">${t('بحث علمي','Research')}</option><option value="resources">${t('مورد موثوق','Trusted resource')}</option></select></label><label>${esc(t('مساهمتك','Your contribution'))}<textarea name="body" maxlength="1500" rows="5" required></textarea></label><button class="button">${esc(t('إرسال للمراجعة','Submit for review'))}</button></form>`:`<p>${esc(t('اربط حسابك للمشاركة والاطلاع على المجتمع.','Connect your account to participate and view the community.'))}</p>${btn('#account',t('ربط حسابي','Connect my account'))}`}</section><section><div class="section-title"><h2>${esc(t('نقاشات المجتمع','Community discussions'))}</h2><span class="tag">${esc(t('آخر 30 مساهمة متاحة','Latest 30 accessible contributions'))}</span></div>${posts.map(p=>`<article class="panel post"><div class="row"><strong>${esc(p.display_name)}</strong>${tag(p.status==='approved'?t('منشور','Published'):t('بانتظار المراجعة','Awaiting review'))}</div><p>${esc(p.body)}</p><small>${esc(new Intl.DateTimeFormat(lang,{dateStyle:'medium'}).format(new Date(p.created_at)))}</small></article>`).join('')||`<div class="empty">${esc(t('لا توجد مساهمات محمّلة. ابدأ بسؤال واضح أو مرجع مفيد.','No contributions loaded. Start with a focused question or useful reference.'))}</div>`}</section></div>`}
function offline(){return `<div class="intro"><span class="eyebrow">NABD · LEARNING THAT STAYS WITH YOU</span><h2>${esc(t('ينقطع الإنترنت.\nوتستمر المعرفة.','The connection stops.\nYour learning continues.'))}</h2><p>${esc(t('صُممت الحزمة لتكون خفيفة: ملخصات نصية أصلية وأسئلة ومراجع. احفظها عندما يتوفر الاتصال، ثم اقرأ وراجع دون إنترنت.','A lightweight pack of original text summaries, questions and references. Save it while connected, then read and practice offline.'))}</p></div><div class="dashboard-grid"><section class="panel offline-card"><div class="download-icon">${icon('download')}</div><h2>${esc(t('حزمة نبض التأسيسية','NABD foundation pack'))}</h2><p>${CATALOG.lessons.length} ${esc(t('دروس · مصطلحات، تشريح، فيزيولوجيا وبحث علمي','lessons · Terminology, anatomy, physiology and research'))}</p><ul class="spaced-list"><li>${esc(t('الدروس والاختبارات والخريطة تعمل دون اتصال بعد الحفظ.','Lessons, quizzes and graph work offline after saving.'))}</li><li>${esc(t('لا تتضمن تسجيلات فيديو أو كتبًا خارجية أو بيانات الحساب.','No video recordings, external books or account data are included.'))}</li><li>${esc(t('المراجع الخارجية وAI والسجلات الرسمية تحتاج اتصالًا.','External references, AI and official records need connectivity.'))}</li></ul><div class="actions"><button class="button" id="save-offline">${esc(t('حفظ الحزمة على هذا الجهاز','Save pack on this device'))}${icon('download')}</button><button class="button secondary" id="export-pack">${esc(t('تنزيل نسخة للقراءة','Download reading copy'))}</button></div><p id="offline-status" role="status">${esc(offlineState)}</p></section><aside class="panel"><span class="eyebrow">YOU CONTROL YOUR DEVICE</span><h2>${esc(t('خفيفة، وتحت سيطرتك','Lightweight, under your control'))}</h2><p>${esc(t('لا تحفظ الحزمة كلمات المرور أو محتوى الحساب. يُحفظ تقدم التدريب العام محليًا فقط. على جهاز مشترك، سجّل الخروج من حسابك بعد الاستخدام.','The pack does not cache passwords or account content. Public practice progress stays on this device. On a shared device, sign out after use.'))}</p><div class="stack"><button class="button secondary" id="remove-offline">${esc(t('إزالة الحزمة المحفوظة','Remove saved pack'))}</button><button class="button secondary" id="clear-practice">${esc(t('مسح تقدّم التدريب المحلي','Clear local practice progress'))}</button></div><small>${esc(t('لا تؤثر هذه الأزرار في بياناتك أو شهاداتك على الخادم.','These actions do not affect your server records or certificates.'))}</small></aside></div>`}
function account(){return `<section class="panel account-panel"><span class="eyebrow">YOUR EXISTING NABD ACCOUNT</span><h2>${esc(t('رحلتك مستمرة، بنفس الحساب.','Continue with your existing account.'))}</h2><p>${esc(t('استخدم البريد وكلمة المرور الحاليين. لن ننشئ سجل طالب جديدًا أو ننقل شهاداتك.','Use your current email and password. We do not create a replacement student record or move your certificates.'))}</p>${accountStatus?`<p class="notice-inline">${esc(accountStatus)}</p>`:''}${user?`<div class="account-profile"><strong>${esc(profile?.full_name||t('طالب نبض','NABD learner'))}</strong><span>${esc(user.email||'')}</span></div><div class="actions">${btn('#universe',t('افتح عالمي التعليمي','Open Student Universe'))}<button class="button secondary" id="sign-out">${esc(t('تسجيل الخروج','Sign out'))}</button></div>`:`<form id="account-form"><label>${esc(t('البريد الإلكتروني','Email'))}<input name="email" type="email" autocomplete="username" required></label><label>${esc(t('كلمة المرور','Password'))}<input name="password" type="password" autocomplete="current-password" required></label><button class="button">${esc(t('تسجيل الدخول','Sign in'))}</button></form>`}<p><a class="text-link" href="../portal.html">${esc(t('إنشاء حساب أو استعادة كلمة المرور في البوابة الحالية','Create an account or recover your password in the existing portal'))} ${icon('arrow')}</a></p></section>`}
function cloudCourse(id){const lessons=cloudLessons.filter(l=>String(l.course_id)===id);return `<div class="intro"><span class="eyebrow">YOUR ENROLLED COURSE</span><h2>${esc(titleCourse(id))}</h2><p>${esc(t('دروس الدورة المنشورة والنتائج المحفوظة لحسابك. الاختبارات هنا تصحّح على الخادم.','Published course lessons and account results. These quizzes are graded on the server.'))}</p></div>${lmsStatus?`<p class="notice-inline">${esc(lmsStatus)}</p>`:''}${!user?btn('#account',t('سجّل الدخول لعرض الدورة','Sign in to view this course')):lessons.length?lessons.map(l=>`<article class="panel course-lesson" data-cloud-lesson="${esc(l.id)}">${tag(l.kind==='assignment'?t('واجب','Assignment'):t('درس','Lesson'))}<h3>${esc(l.title)}</h3><p class="prewrap">${esc(l.body)}</p>${safeURL(l.resource_url)?`<a class="text-link" href="${esc(safeURL(l.resource_url))}" target="_blank" rel="noopener noreferrer">${esc(t('المورد التعليمي','Learning resource'))} ${icon('arrow')}</a>`:''}<p>${esc(l.objective||'')}</p>${cloudProgress.some(p=>p.lesson_id===l.id)?tag(t('تمّت القراءة في الحساب','Marked read in your account')):`<button class="button secondary" data-cloud-read="${esc(l.id)}">${esc(t('تسجيل قراءة الدرس','Save lesson as read'))}</button>`}${cloudQuestions.some(q=>q.lesson_id===l.id)?`<form class="cloud-quiz" data-cloud-quiz="${esc(l.id)}"><h4>${esc(t('اختبار الدورة','Course quiz'))}</h4>${cloudQuestions.filter(q=>q.lesson_id===l.id).map(q=>`<fieldset><legend>${esc(q.prompt)}</legend>${q.choices.map((c,i)=>`<label class="choice"><input type="radio" name="${esc(q.id)}" value="${i}" required>${esc(c)}</label>`).join('')}</fieldset>`).join('')}<button class="button">${esc(t('إرسال للتصحيح','Submit for grading'))}</button></form>`:''}${l.kind==='assignment'?`<form data-assignment="${esc(l.id)}"><label>${esc(t('إجابتك على الواجب','Your assignment answer'))}<textarea name="body" maxlength="6000" rows="4" required></textarea></label><button class="button">${esc(t('إرسال للمراجعة','Submit for review'))}</button></form>`:''}<div class="cloud-result" role="status"></div>${cloudSubmissions.filter(s=>s.lesson_id===l.id).map(s=>`<div class="feedback"><strong>${esc(s.reviewed_at?t('مراجعة الواجب','Assignment review'):t('الواجب بانتظار المراجعة','Assignment awaiting review'))}</strong>${s.grade!==null?`<p>${s.grade}/100</p>`:''}${s.feedback?`<p class="prewrap">${esc(s.feedback)}</p>`:''}</div>`).join('')}${cloudAttempts.filter(a=>a.lesson_id===l.id).slice(0,1).map(a=>`<p>${esc(t('آخر نتيجة محمّلة','Latest loaded result'))}: ${a.score}/${a.total}</p>`).join('')}</article>`).join(''):`<p class="empty">${esc(t('لا توجد دروس محمّلة لهذه الدورة. المواد القديمة متاحة في بوابتك الحالية.','No lessons loaded for this course. Existing materials remain in your current portal.'))}</p>`}<div class="actions">${btn('../portal.html',t('بوابة الطالب الحالية','Existing student portal'),true)}${btn('../lecturers.html',t('موارد المحاضرين','Lecturer resources'),true)}</div>`}
function render(){
 route=location.hash.slice(1)||'universe';if(!nav.some(n=>n[0]===route)&&!['account'].includes(route)&&!/^lesson\/[a-z0-9-]+$/.test(route)&&!/^course\/[^/]+$/.test(route))route='universe';
 if(route.startsWith('course/')){try{decodeURIComponent(route.split('/')[1])}catch{route='universe'}}
 shell();const views={universe,learn,tutor,library,graph,rounds:roundsView,scholarships,community,offline,account};
 $('view').innerHTML=route.startsWith('lesson/')?lessonView(route.split('/')[1]):route.startsWith('course/')?cloudCourse(decodeURIComponent(route.split('/')[1])):views[route]();
 if(route==='offline')inspectOffline();
}
function loadScript(url){return new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=url;script.onload=resolve;script.onerror=()=>reject(Error('Script load failed'));document.head.append(script);setTimeout(()=>reject(Error('Connection timeout')),7000)})}
async function startBackend(){
 if(db)return db;if(!navigator.onLine)throw Error('Offline');if(backendPromise)return backendPromise;
 backendPromise=(async()=>{await loadScript('../assets/js/config.js');await loadScript('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.119.0');const cfg=window.NABD_CONFIG;if(!cfg?.supabaseUrl||!cfg.supabaseAnonKey||!window.supabase)throw Error('Configuration unavailable');db=window.supabase.createClient(cfg.supabaseUrl,cfg.supabaseAnonKey);db.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'){epoch++;user=null;profile=null;enrollments=[];certificates=[];cloudCourses=[];cloudLessons=[];cloudQuestions=[];cloudProgress=[];cloudAttempts=[];cloudSubmissions=[];posts=[];accountStatus='';lmsStatus='';render()}});return db})().catch(error=>{backendPromise=null;throw error});return backendPromise;
}
async function loadAccount(){
 const token=++epoch;try{await startBackend();const auth=await db.auth.getUser();if(token!==epoch)return;user=auth.data?.user||null;if(!user){accountReady=true;try{rounds=await checked(db.from('nabd_learning_rounds').select('*').eq('published',true).order('starts_at').limit(20));roundsStatus=''}catch(error){roundsStatus=statusMessage(error)}if(token!==epoch)return;render();return}
 const results=await Promise.allSettled([checked(db.from('profiles').select('*').eq('id',user.id).maybeSingle()),checked(db.from('enrollments').select('*').eq('student_id',user.id).order('enrolled_at',{ascending:false}).limit(30)),checked(db.from('certificates').select('*').eq('student_id',user.id).order('issue_date',{ascending:false}).limit(30)),checked(db.from('courses').select('*').limit(200))]);
 if(token!==epoch)return;[profile,enrollments,certificates,cloudCourses]=results.map((r,i)=>r.status==='fulfilled'?r.value:i===0?null:[]);accountStatus=results.some(r=>r.status==='rejected')?t('بعض سجلات حسابك لم تُحمّل؛ يمكنك مراجعتها في البوابة الحالية.','Some account records could not be loaded; check the existing portal.'):'';accountReady=true;render();await loadLearning(token);
 }catch(error){if(token!==epoch)return;accountStatus=t('تعذر ربط الحساب الآن؛ التعلّم العام ما زال متاحًا.','Account connection is unavailable; public learning remains available.');accountReady=true;if(['account','universe'].includes(route))render()}
}
async function loadLearning(token=epoch){
 if(!db||!user)return;
 const entries=[['lessons',db.from('nabd_lms_lessons').select('*').order('position').limit(100)],['questions',db.from('nabd_lms_questions').select('id,lesson_id,prompt,choices,position').order('position').limit(300)],['progress',db.from('nabd_lms_progress').select('*').eq('student_id',user.id).limit(300)],['attempts',db.from('nabd_lms_attempts').select('id,lesson_id,score,total,created_at').eq('student_id',user.id).order('created_at',{ascending:false}).limit(100)],['submissions',db.from('nabd_lms_submissions').select('*').eq('student_id',user.id).order('submitted_at',{ascending:false}).limit(100)],['rounds',db.from('nabd_learning_rounds').select('*').eq('published',true).order('starts_at').limit(20)],['posts',db.from('nabd_learning_posts').select('*').order('created_at',{ascending:false}).limit(30)]];
 const results=await Promise.all(entries.map(async([id,q])=>{try{return [id,await checked(q),null]}catch(e){return [id,[],e]}}));if(token!==epoch)return;
 for(const [id,data,error] of results){if(id==='lessons')cloudLessons=data;if(id==='questions')cloudQuestions=data;if(id==='progress')cloudProgress=data;if(id==='attempts')cloudAttempts=data;if(id==='submissions')cloudSubmissions=data;if(id==='rounds'){rounds=data;roundsStatus=error?statusMessage(error):''}if(id==='posts'){posts=data;communityStatus=error?statusMessage(error):''}}
 lmsStatus=results.slice(0,5).some(r=>r[2])?statusMessage(results.find(r=>r[2])[2]):'';
 if(!document.querySelector('form:focus-within'))render();
}
async function busy(button,action){if(button?.disabled)return;if(button)button.disabled=true;try{await action()}catch(error){notice(statusMessage(error))}finally{if(button?.isConnected)button.disabled=false}}
function updatePractice(id,values){practice[id]={...(practice[id]||{}),...values};if(!write(key,practice))notice(t('تعذر الحفظ على الجهاز؛ قد يكون التخزين ممتلئًا.','Could not save on the device; storage may be full.'))}
async function inspectOffline(){if(!('caches' in window))return;const names=await caches.keys();const ready=names.includes('nabd-learning-public-v1');offlineState=ready?t('الحزمة العامة محفوظة على هذا الجهاز.','The public pack is saved on this device.'):t('الحزمة غير محفوظة بعد.','The pack has not been saved yet.');if(route==='offline'&&$('offline-status'))$('offline-status').textContent=offlineState}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function askTutor(form,button){
 const q=form.elements.question.value.trim();if(!q)return;const target=$('tutor-result');target.textContent=t('جارٍ البحث…','Searching…');
 if(button.value!=='ai'){
  if(form.elements.image.files.length){target.textContent=t('البحث المرجعي لا يحلّل الصور. استخدم المساعد التوليدي بعد تفعيله.','Reference search cannot analyze images. Use the generative tutor after activation.');return}
  const terms=q.toLocaleLowerCase().split(/[\s،؟?]+/).filter(x=>x.length>2&&!['اشرح','معنى','الفرق','بين','explain','what','does','the','and','how','أجزاء'].includes(x));
  const matches=CATALOG.lessons.filter(l=>terms.some(w=>JSON.stringify([l.title,l.sections,l.topic]).toLocaleLowerCase().includes(w))||(/heart|قلب|القلب|شريان|الوريد|arter|vein/i.test(q)&&l.id==='circulation')||(/مصطلح|المصطلح|term|word|brady/i.test(q)&&l.id==='medical-words')||(/سبب|السببية|causa|evidence/i.test(q)&&l.id==='evidence')).slice(0,2);
  target.innerHTML=matches.length?`<span class="tag">${esc(t('مقتطفات مرجعية · ليست إجابة مولّدة','Reference excerpts · Not a generated answer'))}</span>${matches.map(l=>`<h3>${esc(text(l.title))}</h3><p>${esc(text(l.sections[0].text))}</p><a class="text-link" href="#lesson/${l.id}">${esc(t('اقرأ الدرس كاملًا','Read the full lesson'))}</a>`).join('')}<div class="sources">${sourceLinks(relatedSources(CATALOG,matches).map(s=>s.id))}</div>`:esc(t('لا توجد فقرة مناسبة في الحزمة لهذا السؤال. جرّب مصطلحًا أبسط أو ابحث في المكتبة.','No matching passage in this pack. Try a simpler term or search the library.'));return;
 }
 if(!user||!db){target.textContent=t('اربط حسابك أولًا. يحتاج التوليد تفعيل الخدمة من الإدارة.','Connect your account first. Generation also requires academy service activation.');return}
 if(!navigator.onLine){target.textContent=t('المساعد التوليدي يحتاج اتصالًا. استخدم الحزمة المرجعية دون إنترنت.','The generative tutor needs connectivity. Use the reference pack offline.');return}
 let image=null;const file=form.elements.image.files[0];if(file){if(!['image/png','image/jpeg'].includes(file.type)||file.size>2*1024*1024){target.textContent=t('اختر PNG أو JPEG بحجم لا يتجاوز 2MB.','Choose PNG or JPEG no larger than 2MB.');return}image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}
 let result;try{result=await db.functions.invoke('nabd-tutor',{body:{question:q,language:lang,image}})}catch(error){result={error}}
 const {data,error}=result;
 if(error||!data?.answer){target.textContent=tutorFailureText(await tutorFailure(result),lang);target.classList.add('prewrap');return}
 target.replaceChildren();const label=document.createElement('span');label.className='tag';label.textContent=t('إجابة مولّدة · تحقّق من المصادر','Generated answer · Verify against sources');const answer=document.createElement('p');answer.className='prewrap';answer.textContent=data.answer;target.append(label,answer);
 const sources=document.createElement('div');sources.className='sources';sources.innerHTML=sourceLinks(Array.isArray(data.source_ids)?data.source_ids.filter(id=>CATALOG.sources.some(s=>s.id===id)):[]);target.append(sources);form.elements.image.value='';
}
$('view').addEventListener('submit',event=>{event.preventDefault();const form=event.target,button=event.submitter;
 busy(button,async()=>{
  if(form.id==='practice-quiz'){const l=CATALOG.lessons.find(l=>l.id===form.dataset.lesson),answers=Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,Number(v)]));const result=gradePractice(l,answers);updatePractice(l.id,{score:Math.max(Number(practice[l.id]?.score)||0,result.score)});$('practice-result').innerHTML=`<h3>${result.score}/${result.total}</h3><p>${esc(t('نتيجة تدريبية على هذا الجهاز؛ ليست تقييمًا رسميًا.','Device practice result; not an official assessment.'))}</p>${result.feedback.map((f,i)=>`<p class="feedback ${f.correct?'correct':'incorrect'}"><b>${i+1}. ${f.correct?t('صحيح','Correct'):t('راجع الإجابة','Review this answer')}</b><br>${esc(text(f.explanation))}</p>`).join('')}`;return}
  if(form.id==='tutor-form'){await askTutor(form,button);return}
  if(form.id==='account-form'){if(!navigator.onLine){notice(t('تسجيل الدخول يحتاج اتصالًا.','Sign-in requires connectivity.'));return}await startBackend();const result=await db.auth.signInWithPassword({email:form.elements.email.value.trim(),password:form.elements.password.value});if(result.error){notice(t('تعذر الدخول. تحقق من البريد وكلمة المرور.','Sign-in failed. Check your email and password.'));return}form.reset();await loadAccount();location.hash='universe';return}
  if(!user||!db){notice(t('سجّل الدخول أولًا.','Sign in first.'));return}
  if(form.id==='community-form'){const f=new FormData(form);await checked(db.from('nabd_learning_posts').insert({author_id:user.id,display_name:f.get('display_name').trim(),topic:f.get('topic'),body:f.get('body').trim(),status:'pending'}).select().single());form.reset();notice(t('أُرسلت مساهمتك للمراجعة قبل النشر.','Your contribution was sent for review before publication.'));await loadLearning();return}
  if(form.dataset.cloudQuiz){const answers=Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,Number(v)]));const result=await checked(db.rpc('nabd_lms_grade_quiz',{p_lesson:form.dataset.cloudQuiz,p_answers:answers}));const out=form.closest('.course-lesson').querySelector('.cloud-result');out.textContent=t('نتيجتك المحفوظة: ','Your saved score: ')+result.score+'/'+result.total;for(const f of result.feedback||[]){const p=document.createElement('p');p.textContent=(f.correct?'✓ ':'• ')+(f.explanation||'');out.append(p)}return}
  if(form.dataset.assignment){await checked(db.rpc('nabd_lms_submit_assignment',{p_lesson:form.dataset.assignment,p_body:form.elements.body.value.trim()}));form.closest('.course-lesson').querySelector('.cloud-result').textContent=t('حُفظ الواجب للمراجعة. إعادة الإرسال تستبدل إجابتك وتعيدها للمراجعة.','Assignment saved for review. Resubmitting replaces your answer and returns it to review.');return}
 });
});
$('view').addEventListener('click',event=>{
 const button=event.target.closest('button');if(!button)return;
 if(button.dataset.read){updatePractice(button.dataset.read,{completed:true});button.innerHTML=esc(t('قرأت هذا الدرس ✓','Marked as read ✓'));return}
 if(button.dataset.bookmark){bookmarks=bookmarks.includes(button.dataset.bookmark)?bookmarks.filter(id=>id!==button.dataset.bookmark):[...bookmarks,button.dataset.bookmark];write('nabd-learning-bookmarks',bookmarks);const container=$('library-results');container.innerHTML=libraryCards($('library-topic').value);return}
 if(button.dataset.node){activeNode=button.dataset.node;render();return}
 if(button.dataset.suggest){$('tutor-form').elements.question.value=button.dataset.suggest;$('tutor-form').elements.question.focus();return}
 if(button.dataset.discussion!==undefined){discussionStep=Number(button.dataset.discussion);render();return}
 busy(button,async()=>{
  if(button.dataset.cloudRead){if(!user||!db)throw Error('Not authenticated');await checked(db.rpc('nabd_lms_complete_lesson',{p_lesson:button.dataset.cloudRead}));await loadLearning();notice(t('حُفظت قراءة الدرس في حسابك.','Lesson read status saved to your account.'))}
  if(button.id==='sign-out'){const r=await db.auth.signOut();if(r.error)throw r.error;notice(t('تم تسجيل الخروج.','Signed out.'))}
  if(button.id==='save-offline'){
   if(!('serviceWorker' in navigator)||!window.isSecureContext){notice(t('الحفظ دون إنترنت يحتاج متصفحًا يدعم الميزة واتصال HTTPS. يمكنك تنزيل نسخة القراءة.','Offline saving needs a supported browser and HTTPS. You can download the reading copy.'));return}
   if(!navigator.onLine){notice(t('اتصل بالإنترنت مرة واحدة لحفظ الحزمة.','Connect once to save the pack.'));return}
   await navigator.serviceWorker.register('./sw.js',{scope:'./'});
   await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(Error('Offline installation timed out')),20000))]);
   await inspectOffline();notice(offlineState);
  }
  if(button.id==='export-pack'){const body=`<!doctype html><html lang="${lang}" dir="${lang==='ar'?'rtl':'ltr'}"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NABD · Foundation reading pack</title><style>body{font:17px/1.9 system-ui;max-width:850px;margin:30px auto;padding:20px;color:#102d3a}article{border-bottom:1px solid #ccd;padding:20px 0}a{color:#176660}.icon{width:16px;height:16px;vertical-align:middle}.sources{display:grid;gap:8px}h1,h2,h3{line-height:1.5}</style><h1>${esc(t('أكاديمية نبض للعلوم الطبية · حزمة القراءة','NABD Academy for Medical Sciences · Reading pack'))}</h1><p>${esc(t('ملخصات أصلية للتعلّم الذاتي. الروابط الخارجية تحتاج اتصالًا. لا تتضمن بيانات حسابك.','Original self-study summaries. External links need connectivity. No account data is included.'))}</p>${CATALOG.lessons.map(l=>`<article><h2>${esc(text(l.title))}</h2><p>${esc(text(l.objectives))}</p>${l.sections.map(s=>`<h3>${esc(text(s.heading))}</h3><p>${esc(text(s.text))}</p>`).join('')}<h3>${esc(t('مراجعة ذاتية','Self-review'))}</h3>${l.quiz.map(q=>`<details><summary>${esc(text(q.prompt))}</summary><p>${esc(text(q.choices[q.answer]))}: ${esc(text(q.explanation))}</p></details>`).join('')}<h3>${esc(t('المصادر','Sources'))}</h3>${sourceLinks(l.source_ids)}</article>`).join('')}</html>`;download('nabd-foundation-reading.html',body,'text/html;charset=utf-8');notice(t('تم تجهيز نسخة القراءة للتنزيل.','Reading copy prepared for download.'))}
  if(button.id==='remove-offline'){if('caches' in window)for(const name of await caches.keys())if(name.startsWith('nabd-learning-public-'))await caches.delete(name);if('serviceWorker' in navigator)for(const reg of await navigator.serviceWorker.getRegistrations())if(reg.scope===new URL('./',location.href).href)await reg.unregister();await inspectOffline();notice(t('أُزيلت حزمة التعلّم المحفوظة؛ لم تتغيّر بيانات حسابك.','Saved learning pack removed; account data was not changed.'))}
  if(button.id==='clear-practice'){practice={};try{localStorage.removeItem(key)}catch{}notice(t('مُسح تقدم التدريب على هذا الجهاز فقط.','Device practice progress cleared.'))}
 });
});
$('view').addEventListener('click',event=>{const node=event.target.closest('g[data-node]');if(node){activeNode=node.dataset.node;render()}});
$('view').addEventListener('input',event=>{if(event.target.id==='search'){query=event.target.value;if(route==='learn')$('results').innerHTML=searchLessons(CATALOG,query).map(lessonCard).join('')||`<p class="empty">${t('لا توجد نتائج.','No results.')}</p>`;if(route==='library')$('library-results').innerHTML=libraryCards($('library-topic').value)}});
$('view').addEventListener('change',event=>{if(event.target.id==='library-topic'){write('nabd-learning-library-topic',event.target.value);$('library-results').innerHTML=libraryCards(event.target.value)}if(event.target.dataset.checklist){const state=read('nabd-learning-checklist',{});state[event.target.dataset.checklist]=event.target.checked;write('nabd-learning-checklist',state)}});
$('language').onclick=()=>{lang=lang==='ar'?'en':'ar';write('nabd-learning-language',lang);query='';render()};
window.addEventListener('hashchange',()=>{query='';notice('');render();$('workspace').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})});
window.addEventListener('offline',()=>{epoch++;user=null;profile=null;enrollments=[];certificates=[];cloudCourses=[];cloudLessons=[];cloudQuestions=[];cloudProgress=[];cloudAttempts=[];cloudSubmissions=[];posts=[];rounds=[];accountStatus=t('أنت دون اتصال؛ سجلات الحساب غير معروضة.','You are offline; account records are not displayed.');render()});
window.addEventListener('online',()=>{shell();loadAccount()});
render();if(navigator.onLine)loadAccount();
